// Flatten whatever your form or CRM posts into one text block for the model,
// plus the raw fields for downstream nodes. Adjust the field names to your form.
const b = $json.body ?? $json;

const text = [
  `Name: ${b.name ?? [b.first_name, b.last_name].filter(Boolean).join(' ') ?? 'not provided'}`,
  `Email: ${b.email ?? 'not provided'}`,
  `Company: ${b.company ?? b.companyName ?? 'not provided'}`,
  `Employees: ${b.employees ?? 'not provided'}`,
  `Budget: ${b.budget ?? 'not provided'}`,
  '',
  'Enquiry:',
  '"""',
  String(b.message ?? b.inquiry ?? b.notes ?? ''),
  '"""',
].join('\n');

if (!String(b.message ?? b.inquiry ?? b.notes ?? '').trim()) {
  throw new Error('No enquiry text on the inbound lead — nothing to qualify.');
}

return [{ json: { leadText: text } }];

// ── Deterministic routing ────────────────────────────────────────────────────
// The model proposed a score and a confidence. THIS node decides what happens.
// Nothing above here can select a route on its own.

// 1. Parse the Anthropic response.
//    The Messages API returns { content: [ { type: 'text', text: '...' } ] }.
//    Reading $json.lead_score directly is the classic mistake — it is undefined,
//    every lead silently scores 0, and everything routes to low priority.
const block = ($json.content ?? []).find((b) => b.type === 'text');
if (!block) throw new Error(`No text block in Claude response (stop_reason=${$json.stop_reason})`);

let a;
try {
  a = JSON.parse(block.text);
} catch (e) {
  throw new Error(`Claude did not return valid JSON: ${block.text.slice(0, 200)}`);
}

// 2. Validate. Structured outputs make bad shapes rare, not impossible, and a
//    missing field must fail loudly rather than default to zero.
const score = Number(a.lead_score);
const confidence = Number(a.confidence);
if (!Number.isFinite(score) || !Number.isFinite(confidence)) {
  throw new Error(`Missing lead_score or confidence: ${block.text.slice(0, 200)}`);
}

// 3. Thresholds — edit these, they are the whole business policy.
const HOT_SCORE = 80, HOT_CONFIDENCE = 0.80;
const WARM_SCORE = 50, WARM_CONFIDENCE = 0.70;

// 4. Two gates, not one.
//    A lead must clear BOTH the score and the confidence gate for its tier.
//    Clearing the score but not the confidence drops it exactly ONE tier —
//    never straight to archive.
//
//    Why the asymmetry: a sales call costs an hour of someone's time, a nurture
//    sequence costs almost nothing, and archiving is the only irreversible
//    outcome. So low confidence may block an escalation, but must never throw a
//    lead away. That decision belongs to the score alone.
let route, appliedRule;

if (score >= HOT_SCORE) {
  if (confidence >= HOT_CONFIDENCE) {
    route = 'hot';  appliedRule = 'hot_score_and_confidence';
  } else {
    route = 'warm'; appliedRule = 'hot_downgraded_low_confidence';
  }
} else if (score >= WARM_SCORE) {
  if (confidence >= WARM_CONFIDENCE) {
    route = 'warm'; appliedRule = 'warm_score_and_confidence';
  } else {
    route = 'cold'; appliedRule = 'warm_downgraded_low_confidence';
  }
} else {
  route = 'cold';   appliedRule = 'score_below_warm_threshold';
}

return [{
  json: {
    route,
    applied_rule: appliedRule,
    lead_score: score,
    confidence,
    reason: a.reason ?? '',
    industry: a.industry ?? 'Unknown',
    next_action: route === 'hot' ? 'sales_call'
               : route === 'warm' ? 'nurture_sequence' : 'archive',
    lead: $('Receive lead').item.json.body ?? {},
  },
}];
